messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Walk / Run Cycle — Low-Poly Figure</title>
<style>
  html, body { margin: 0; height: 100%; overflow: hidden; background: #0e0f12; }
  #stage { width: 100%; height: 100%; }
  #label {
    position: fixed; left: 50%; bottom: 28px; transform: translateX(-50%);
    font-family: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
    font-size: 13px; letter-spacing: 3px; color: #d8d2c4;
    text-transform: uppercase; user-select: none; pointer-events: none;
  }
  #bar {
    position: fixed; left: 50%; bottom: 14px; transform: translateX(-50%);
    width: 220px; height: 2px; background: rgba(216,210,196,0.18);
    pointer-events: none;
  }
  #bar > div { height: 100%; width: 0%; background: #d8d2c4; }
</style>
</head>
<body>
<div id="stage"></div>
<div id="label">stand</div>
<div id="bar"><div></div></div>

<script type="module">
import * as THREE from './three.module.js';

/* ------------------------------------------------------------------ setup */
const stage = document.getElementById('stage');
const label = document.getElementById('label');
const barFill = document.querySelector('#bar > div');

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
stage.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x101114);
scene.fog = new THREE.Fog(0x101114, 14, 30);

const camera = new THREE.PerspectiveCamera(42, innerWidth / innerHeight, 0.1, 100);
camera.position.set(0, 1.55, 8.2);
camera.lookAt(0, 1.0, 0);

/* ---------------------------------------------------------------- lights */
scene.add(new THREE.HemisphereLight(0xcfd6e0, 0x2a2620, 0.85));

const sun = new THREE.DirectionalLight(0xfff3e0, 1.6);
sun.position.set(4, 7, 5);
sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
sun.shadow.camera.left = -6; sun.shadow.camera.right = 6;
sun.shadow.camera.top = 6;   sun.shadow.camera.bottom = -6;
sun.shadow.camera.far = 20;
sun.shadow.bias = -0.0005;
scene.add(sun);

const rim = new THREE.DirectionalLight(0x88a0c0, 0.5);
rim.position.set(-5, 3, -4);
scene.add(rim);

/* ---------------------------------------------------------------- ground */
/* treadmill-style: a long dark belt with moving lane stripes + side rails */
const beltGeo = new THREE.BoxGeometry(2.6, 0.18, 22);
const beltMat = new THREE.MeshStandardMaterial({ color: 0x23262b, roughness: 0.9, metalness: 0.05 });
const belt = new THREE.Mesh(beltGeo, beltMat);
belt.position.y = -0.09;
belt.receiveShadow = true;
scene.add(belt);

const stripeMat = new THREE.MeshStandardMaterial({ color: 0x3a4048, roughness: 0.9 });
const stripes = [];
for (let i = 0; i < 22; i++) {
  const s = new THREE.Mesh(new THREE.BoxGeometry(2.3, 0.02, 0.12), stripeMat);
  s.position.set(0, 0.011, -11 + i * 1.0);
  stripes.push(s);
  scene.add(s);
}

const railMat = new THREE.MeshStandardMaterial({ color: 0x565b64, roughness: 0.5, metalness: 0.4 });
for (const z0 of [-11, 11]) {
  const cap = new THREE.Mesh(new THREE.BoxGeometry(2.9, 0.1, 0.3), railMat);
  cap.position.set(0, 0.05, z0);
  cap.castShadow = true;
  scene.add(cap);
}
for (const x0 of [-1.45, 1.45]) {
  const rail = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.08, 22), railMat);
  rail.position.set(x0, 0.04, 0);
  scene.add(rail);
}

/* wide matte floor around the belt */
const floor = new THREE.Mesh(
  new THREE.PlaneGeometry(60, 60),
  new THREE.MeshStandardMaterial({ color: 0x191b1f, roughness: 1 })
);
floor.rotation.x = -Math.PI / 2;
floor.position.y = -0.19;
floor.receiveShadow = true;
scene.add(floor);

/* ---------------------------------------------------------------- figure */
/* low-poly humanoid built from boxes, pivoted at shoulders/hips */
const skin = new THREE.MeshStandardMaterial({ color: 0xd8a06a, roughness: 0.75, flatShading: true });
const cloth = new THREE.MeshStandardMaterial({ color: 0x3f6e8c, roughness: 0.85, flatShading: true });
const pants = new THREE.MeshStandardMaterial({ color: 0x3a3f47, roughness: 0.9, flatShading: true });
const shoe  = new THREE.MeshStandardMaterial({ color: 0xc9c2b2, roughness: 0.7, flatShading: true });

function box(w, h, d, mat) {
  const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
  m.castShadow = true;
  return m;
}

const root = new THREE.Group();      // whole figure (bobbing / lean)
scene.add(root);

/* torso */
const torso = box(0.62, 0.78, 0.34, cloth);
torso.position.y = 1.28;
root.add(torso);

/* hips block */
const hips = box(0.5, 0.24, 0.3, pants);
hips.position.y = 0.84;
root.add(hips);

/* head + simple face detail */
const neck = box(0.14, 0.12, 0.14, skin);
neck.position.y = 1.74;
root.add(neck);

const head = box(0.34, 0.36, 0.32, skin);
head.position.y = 1.98;
root.add(head);

const hair = box(0.36, 0.12, 0.34, new THREE.MeshStandardMaterial({ color: 0x2c2620, roughness: 1, flatShading: true }));
hair.position.y = 2.18;
root.add(hair);

const nose = box(0.06, 0.08, 0.06, skin);
nose.position.set(0, 1.98, 0.18);
root.add(nose);

/* limbs: pivot groups so rotation happens at shoulder / hip joints */
function makeArm(side) {
  const pivot = new THREE.Group();
  pivot.position.set(0.41 * side, 1.6, 0);
  const upper = box(0.16, 0.42, 0.16, cloth);
  upper.position.y = -0.21;
  pivot.add(upper);
  const fore = box(0.14, 0.38, 0.14, skin);
  fore.position.y = -0.58;
  pivot.add(fore);
  const hand = box(0.15, 0.12, 0.1, skin);
  hand.position.y = -0.82;
  pivot.add(hand);
  root.add(pivot);
  return pivot;
}

function makeLeg(side) {
  const pivot = new THREE.Group();
  pivot.position.set(0.17 * side, 0.82, 0);
  const thigh = box(0.2, 0.44, 0.2, pants);
  thigh.position.y = -0.22;
  pivot.add(thigh);
  const shin = box(0.17, 0.42, 0.17, pants);
  shin.position.y = -0.62;
  pivot.add(shin);
  const foot = box(0.18, 0.12, 0.32, shoe);
  foot.position.set(0, -0.88, 0.06);
  pivot.add(foot);
  root.add(pivot);
  return pivot;
}

const armL = makeArm(-1), armR = makeArm(1);
const legL = makeLeg(-1), legR = makeLeg(1);

/* ------------------------------------------------------- phase timeline */
/* 10 s loop: stand 2s -> walk 3s -> run 3s -> stand 2s */
const T_STAND1 = 0, T_WALK = 2, T_RUN = 5, T_STAND2 = 8, T_TOTAL = 10;

function phase(t) {
  if (t < T_WALK)  return { name: 'stand',  k: t / 2 };
  if (t < T_RUN)   return { name: 'walk',   k: (t - T_WALK) / 3 };
  if (t < T_STAND2)return { name: 'run',    k: (t - T_RUN) / 3 };
  return             { name: 'stand', k: (t - T_STAND2) / 2 };
}

/* smooth blend factor in/out of an active phase (0..1..0) */
function envelope(k) {
  const e = Math.min(k, 1 - k) / 0.18;   // 18% ramp at each end
  return Math.max(0, Math.min(1, e));
}

/* ------------------------------------------------------------- animation */
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const t = (clock.getElapsedTime() % T_TOTAL);
  const p = phase(t);

  let amp = 0, freq = 0, lean = 0, bob = 0, stride = 0, elbow = 0;

  if (p.name === 'walk') {
    const e = envelope(p.k);
    amp = 0.62 * e;       // moderate swing
    freq = 5.6;           // walking pace
    lean = 0.05 * e;
    bob = 0.035 * e;
    stride = 0.16 * e;
    elbow = 0.35 * e;
  } else if (p.name === 'run') {
    const e = envelope(p.k);
    amp = 1.15 * e;       // large swing
    freq = 9.4;           // fast pace
    lean = 0.28 * e;      // forward lean
    bob = 0.09 * e;
    stride = 0.42 * e;    // strong knee drive
    elbow = 1.1 * e;      // bent pumping arms
  }

  const w = t * freq;
  const swing = Math.sin(w) * amp;

  /* legs: opposite phases, knees bend on the recovery (backward-swinging) leg */
  legL.rotation.x = swing;
  legR.rotation.x = -swing;
  const kneeL = Math.max(0, -Math.sin(w)) * stride + stride * 0.12;
  const kneeR = Math.max(0,  Math.sin(w)) * stride + stride * 0.12;
  legL.children[1].rotation.x = kneeL;
  legR.children[1].rotation.x = kneeR;
  /* ankle flick */
  legL.children[2].rotation.x = -kneeL * 0.5;
  legR.children[2].rotation.x = -kneeR * 0.5;

  /* arms: counter to same-side leg, elbows bent more when running */
  armL.rotation.x = -swing * 0.9;
  armR.rotation.x =  swing * 0.9;
  armL.children[1].rotation.x = -elbow;
  armR.children[1].rotation.x = -elbow;
  /* slight arm abduction so limbs don't intersect torso */
  armL.rotation.z = 0.1 + 0.06 * Math.abs(swing);
  armR.rotation.z = -0.1 - 0.06 * Math.abs(swing);

  /* body: forward lean while running, vertical bob at 2x step frequency */
  root.rotation.x = lean;
  root.position.y = Math.abs(Math.sin(w)) * bob;
  /* tiny lateral sway for life */
  root.position.x = Math.sin(w * 0.5) * 0.02 * (amp / 1.15);

  /* head stays level-ish: counter-lean so figure doesn't tip face-first */
  head.rotation.x = -lean * 0.7;
  neck.rotation.x = -lean * 0.5;

  /* treadmill belt + stripes scroll: speed matches gait */
  const beltSpeed = p.name === 'walk' ? 1.5 : p.name === 'run' ? 4.2 : 0;
  const blend = (p.name === 'stand') ? 0 : beltSpeed;
  beltOffset += blend * (1 / 60);
  for (const s of stripes) {
    s.position.z = ((s.position.z + beltOffset) % 22 + 22) % 22 - 11;
  }

  /* HUD */
  label.textContent = p.name;
  barFill.style.width = (t / T_TOTAL * 100).toFixed(1) + '%';

  renderer.render(scene, camera);
}

let beltOffset = 0;
animate();

addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```
